//! Newstroke, KiCad's stroke font, and KiCad's rules for placing text in
//! it: every text item that names no face draws through here.
//!
//! The glyphs are the generated table in `font/newstroke_table.rs`
//! (regenerated by `newstroke_dev`), decoded as KiCad's `STROKE_FONT`
//! decodes the same strings: coordinates are characters offset from `R`,
//! 21 units to the em, the y origin eight units above the baseline. A
//! glyph's points are in em units, x from its left bearing, y down from
//! the baseline, so a text of size `s` draws each point at `s` times it.
//!
//! [`shape`] lays a text item out as KiCad's `FONT::Draw` does: lines
//! split on newlines and spaced by the interline, each line offset by its
//! justification, glyphs advanced by their widths, then the whole
//! mirrored and turned about the item's position. The numbers (the 1.17
//! first-line height, the stroke-width fudges, the 0.9583 legacy
//! interline factor) are KiCad's, kept so a board looks here as it does
//! there. The `~{}`, `^{}` and `_{}` markup KiCad draws as overbars and
//! super- or subscripts is drawn as written.

mod newstroke_table;
pub mod outline;

use crate::geometry::{Bounds, Transform};
use crate::model::{Font, Horizontal, Justify, Point, Size, Text, Vertical};

/// Em units per coordinate step.
const SCALE: f64 = 1.0 / 21.0;
/// Steps the y origin sits above the baseline in the encoding.
const FONT_OFFSET: f64 = -8.0;
/// The character coordinate 0 is written as.
const ORIGIN: u8 = b'R';
/// What an italic glyph's x shifts per unit of y: KiCad's `ITALIC_TILT`.
const ITALIC_TILT: f64 = 1.0 / 8.0;
/// Baseline to baseline between lines, in text heights: KiCad's default
/// metrics' interline pitch times the stroke font's legacy factor.
const INTERLINE: f64 = 1.68 * 0.9583;
/// The height the first line counts for in the block, in text heights:
/// KiCad's "fudge to match 6.0 positioning".
pub(crate) const FIRST_LINE_HEIGHT: f64 = 1.17;
/// Tab stops every this many space widths.
pub(crate) const TAB_WIDTH: usize = 4;
/// The glyph drawn for a character the table lacks.
const SUBSTITUTE: char = '?';

/// One glyph as the table draws it: strokes in em units, and how far the
/// pen advances after it.
#[derive(Debug, Clone, PartialEq)]
pub struct Glyph {
    /// The polylines, x from the left bearing, y down from the baseline.
    pub strokes: Vec<Vec<Point>>,
    /// The width the next glyph starts after.
    pub advance: f64,
}

/// The glyph for `c`, or the one for `?` when the table has none.
#[must_use]
pub fn glyph(c: char) -> Glyph {
    let encoded = encoded(c)
        .or_else(|| encoded(SUBSTITUTE))
        .unwrap_or_default();
    decode(encoded)
}

/// The table's string for `c`.
fn encoded(c: char) -> Option<&'static str> {
    let index = u32::from(c).checked_sub(newstroke_table::FIRST)?;
    newstroke_table::GLYPHS
        .get(usize::try_from(index).ok()?)
        .copied()
}

/// The advance of a space: the first glyph's width, as KiCad takes it.
fn space_width() -> f64 {
    decode(newstroke_table::GLYPHS.first().copied().unwrap_or_default()).advance
}

/// A coordinate character as a value in steps.
fn step(byte: u8) -> f64 {
    f64::from(i16::from(byte) - i16::from(ORIGIN))
}

/// A table string as a glyph: the first two characters are the left and
/// right bearings, then pairs are points, and ` R` lifts the pen.
fn decode(encoded: &str) -> Glyph {
    let bytes = encoded.as_bytes();
    let (Some(&left), Some(&right)) = (bytes.first(), bytes.get(1)) else {
        return Glyph {
            strokes: Vec::new(),
            advance: 0.0,
        };
    };
    let start_x = step(left) * SCALE;
    let advance = (step(right) - step(left)) * SCALE;
    let mut strokes: Vec<Vec<Point>> = Vec::new();
    let mut pen_down = false;
    for &[x, y] in bytes.get(2..).unwrap_or_default().as_chunks::<2>().0 {
        if x == b' ' && y == ORIGIN {
            pen_down = false;
            continue;
        }
        let point = Point {
            x: step(x) * SCALE - start_x,
            y: (step(y) + FONT_OFFSET) * SCALE,
        };
        if !pen_down {
            strokes.push(Vec::new());
            pen_down = true;
        }
        if let Some(stroke) = strokes.last_mut() {
            stroke.push(point);
        }
    }
    Glyph { strokes, advance }
}

/// The pen width a text draws with: its thickness when the file gives
/// one, else KiCad's default for the size (an eighth of the width, a
/// fifth for bold), and never more than a quarter of the smaller side.
#[must_use]
pub fn pen_width(font: &Font) -> f64 {
    let width = font.size.width.abs();
    let min_side = width.min(font.size.height.abs());
    let pen = match font.thickness {
        Some(thickness) if thickness > 0.0 => thickness,
        _ if font.bold => width / 5.0,
        _ => width / 8.0,
    };
    pen.min(min_side * 0.25)
}

/// The angle a text draws at, in degrees: `rotation` folded into
/// (-90, 90] for an upright footprint text, else as written.
#[must_use]
pub fn draw_angle(rotation: f64, upright_in_footprint: bool) -> f64 {
    let mut angle = rotation.rem_euclid(360.0);
    if upright_in_footprint {
        if angle > 90.0 && angle <= 270.0 {
            angle -= 180.0;
        } else if angle > 270.0 {
            angle -= 360.0;
        }
    }
    angle
}

/// How a text is drawn: the font's size and pen, how it sits on its
/// position, and where that position is on the board.
#[derive(Debug, Clone, PartialEq)]
pub struct Placement {
    /// Glyph height and width, millimetres.
    pub size: Size,
    /// Stroke width, millimetres ([`pen_width`]).
    pub pen: f64,
    /// Italic: glyphs lean right by an eighth of their height.
    pub italic: bool,
    /// Anchoring and mirroring.
    pub justify: Justify,
    /// The anchor on the board.
    pub position: Point,
    /// Degrees, counter-clockwise on the screen ([`draw_angle`]).
    pub angle: f64,
}

impl Placement {
    /// How `text` is drawn at `position` (its anchor carried into the
    /// board's frame): the font's pen width, and its rotation folded
    /// upright when it is a footprint's text that asks for it.
    #[must_use]
    pub fn of(text: &Text, position: Point, in_footprint: bool) -> Self {
        Self {
            size: text.font.size,
            pen: pen_width(&text.font),
            italic: text.font.italic,
            justify: text.justify,
            position,
            angle: draw_angle(text.rotation, in_footprint && text.upright),
        }
    }
}

/// A text laid out on the board.
#[derive(Debug, Clone, PartialEq)]
pub struct TextShape {
    /// The strokes, in board millimetres, to draw at [`TextShape::pen`]
    /// width with round ends.
    pub strokes: Vec<Vec<Point>>,
    /// The stroke width.
    pub pen: f64,
    /// The box a knockout fills around the text: the strokes' bounds
    /// before rotation, grown by half the pen and KiCad's knockout margin
    /// (the larger of half the pen and a ninth of the height), turned
    /// with the text. `None` for an empty text.
    pub knockout_box: Option<[Point; 4]>,
}

/// Lays `text` out as `placement` says.
#[must_use]
pub fn shape(text: &str, placement: &Placement) -> TextShape {
    let size = placement.size;
    let pen = placement.pen;
    let lines: Vec<&str> = text.split('\n').collect();
    let interline = size.height * INTERLINE;
    #[expect(
        clippy::cast_precision_loss,
        reason = "a text has far fewer lines than 2^53"
    )]
    let block_height =
        size.height * FIRST_LINE_HEIGHT + (lines.len().saturating_sub(1)) as f64 * interline;
    // The anchor is the top left of the block before justification; the
    // stroke font's fudges move it slightly right and up.
    let offset_x = pen / 1.52;
    let mut offset_y = size.height - pen * 0.052;
    match placement.justify.vertical {
        Vertical::Top => {}
        Vertical::Center => offset_y -= block_height / 2.0,
        Vertical::Bottom => offset_y -= block_height,
    }
    let origin = placement.position;
    let mut strokes: Vec<Vec<Point>> = Vec::new();
    for (index, line) in lines.iter().enumerate() {
        let width = line_width(line, size);
        let line_offset_x = match placement.justify.horizontal {
            Horizontal::Left => offset_x,
            Horizontal::Center => -width / 2.0,
            Horizontal::Right => -(width + offset_x),
        };
        #[expect(
            clippy::cast_precision_loss,
            reason = "a text has far fewer lines than 2^53"
        )]
        let line_start = Point {
            x: origin.x + line_offset_x,
            y: origin.y + offset_y + index as f64 * interline,
        };
        strokes.extend(line_strokes(line, size, placement.italic, line_start));
    }
    if placement.justify.mirror {
        for stroke in &mut strokes {
            for point in stroke.iter_mut() {
                point.x = origin.x - (point.x - origin.x);
            }
        }
    }
    let knockout_box = Bounds::around(strokes.iter().flatten().copied()).map(|bounds| {
        let margin = (pen / 2.0).max(size.height / 9.0);
        let grow = pen / 2.0 + margin;
        [
            Point {
                x: bounds.min.x - grow,
                y: bounds.min.y - grow,
            },
            Point {
                x: bounds.max.x + grow,
                y: bounds.min.y - grow,
            },
            Point {
                x: bounds.max.x + grow,
                y: bounds.max.y + grow,
            },
            Point {
                x: bounds.min.x - grow,
                y: bounds.max.y + grow,
            },
        ]
    });
    let turn = Transform::new(origin, placement.angle);
    let turned = |p: Point| {
        turn.apply(Point {
            x: p.x - origin.x,
            y: p.y - origin.y,
        })
    };
    for stroke in &mut strokes {
        for point in stroke.iter_mut() {
            *point = turned(*point);
        }
    }
    TextShape {
        strokes,
        pen,
        knockout_box: knockout_box.map(|corners| corners.map(turned)),
    }
}

/// Where the pen is after each character of `line`, from `start`: a
/// glyph advances by its width, a space by the space width, a tab to
/// the next stop of four space widths.
fn cursors(line: &str, size: Size, start: Point) -> Vec<(char, Point)> {
    let space = space_width();
    let mut cursor = start;
    let mut column = 0usize;
    let mut out = Vec::new();
    for c in line.chars() {
        out.push((c, cursor));
        match c {
            '\t' => {
                column = (column / TAB_WIDTH + 1) * TAB_WIDTH - 1;
                #[expect(
                    clippy::cast_precision_loss,
                    reason = "a line has far fewer columns than 2^53"
                )]
                let mut next = start.x + size.width * column as f64 + size.width * space;
                #[expect(clippy::cast_precision_loss, reason = "the tab width is 4")]
                while next <= cursor.x {
                    column += TAB_WIDTH;
                    next += size.width * TAB_WIDTH as f64;
                }
                cursor.x = next;
            }
            ' ' => cursor.x += size.width * space,
            _ => cursor.x += size.width * glyph(c).advance,
        }
        column += 1;
    }
    out.push(('\0', cursor));
    out
}

/// The nominal box of `text` laid out at `size`, before justification
/// and rotation: the widest line's advance by the height of the block
/// (one text height for the first line, one interline for each further
/// line). This is what KiCad's text box is: a schematic places a
/// symbol's fields by the centre of this box, and sizes a label's flag
/// by its width.
#[must_use]
pub fn block_size(text: &str, size: Size) -> Size {
    let lines: Vec<&str> = text.split('\n').collect();
    let width = lines
        .iter()
        .map(|line| line_width(line, size))
        .fold(0.0, f64::max);
    #[expect(
        clippy::cast_precision_loss,
        reason = "a text has far fewer lines than 2^53"
    )]
    let height = size.height + lines.len().saturating_sub(1) as f64 * size.height * INTERLINE;
    Size { width, height }
}

/// The advance of a whole line.
fn line_width(line: &str, size: Size) -> f64 {
    cursors(line, size, Point::default())
        .last()
        .map_or(0.0, |(_, end)| end.x)
}

/// The strokes of one line, unmirrored and unturned.
fn line_strokes(line: &str, size: Size, italic: bool, start: Point) -> Vec<Vec<Point>> {
    let tilt = if italic { ITALIC_TILT } else { 0.0 };
    let mut out = Vec::new();
    for (c, cursor) in cursors(line, size, start) {
        if matches!(c, '\0' | ' ' | '\t') {
            continue;
        }
        for stroke in glyph(c).strokes {
            out.push(
                stroke
                    .into_iter()
                    .map(|p| {
                        let x = p.x * size.width - p.y * size.height * tilt;
                        Point {
                            x: cursor.x + x,
                            y: cursor.y + p.y * size.height,
                        }
                    })
                    .collect(),
            );
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use test_case::test_case;

    use super::*;

    fn close(a: f64, b: f64) -> bool {
        (a - b).abs() < 1e-9
    }

    /// Point `index` of stroke `stroke`: the crate forbids indexing, and a
    /// missing point is a failed test, not a panic in the drawing.
    fn pt(strokes: &[Vec<Point>], stroke: usize, index: usize) -> Point {
        strokes
            .get(stroke)
            .and_then(|s| s.get(index))
            .copied()
            .unwrap_or_else(|| panic!("no point {index} in stroke {stroke} of {strokes:?}"))
    }

    fn assert_point(p: Point, x: f64, y: f64) {
        assert!(close(p.x, x) && close(p.y, y), "{p:?} is not ({x}, {y})");
    }

    #[test]
    fn capital_a_decodes_as_kicad_decodes_it() {
        // "I[MUWU RK[RFY[": bearings I and [ are -9 and 9 steps, so the
        // glyph advances 18/21; its bar runs from M to W at height U, its
        // legs from K and Y on the baseline ([) up to the apex at F.
        let a = glyph('A');
        assert!(close(a.advance, 18.0 / 21.0), "{}", a.advance);
        assert_eq!(a.strokes.len(), 2);
        assert_point(pt(&a.strokes, 0, 0), 4.0 / 21.0, -5.0 / 21.0);
        assert_point(pt(&a.strokes, 0, 1), 14.0 / 21.0, -5.0 / 21.0);
        assert_point(pt(&a.strokes, 1, 0), 2.0 / 21.0, 1.0 / 21.0);
        assert_point(pt(&a.strokes, 1, 1), 9.0 / 21.0, -20.0 / 21.0);
        assert_point(pt(&a.strokes, 1, 2), 16.0 / 21.0, 1.0 / 21.0);
    }

    #[test]
    fn a_character_the_table_lacks_draws_as_a_question_mark() {
        assert_eq!(glyph('\u{10FFFF}'), glyph('?'));
        assert_ne!(glyph('Ω'), glyph('?'));
    }

    #[test_case(Some(0.15), false, 1.0, 0.15; "the thickness as written")]
    #[test_case(None, false, 1.0, 0.125; "an eighth of the width without one")]
    #[test_case(None, false, 1.2, 0.15; "the width, not the smaller side")]
    #[test_case(None, true, 1.0, 0.2; "a fifth when bold")]
    #[test_case(Some(0.4), false, 1.0, 0.25; "capped at a quarter of the smaller side")]
    #[test_case(None, false, 4.0, 0.25; "the default capped too")]
    fn the_pen_is_the_thickness_or_kicads_default_for_the_size(
        thickness: Option<f64>,
        bold: bool,
        width: f64,
        expected: f64,
    ) {
        let font = Font {
            face: None,
            size: Size { width, height: 1.0 },
            thickness,
            bold,
            italic: false,
        };
        let pen = pen_width(&font);
        assert!(close(pen, expected), "{pen}");
    }

    #[test_case(90.0, true, 90.0; "90 stays")]
    #[test_case(270.0, true, 90.0; "270 folds to 90")]
    #[test_case(180.0, true, 0.0; "180 folds to 0")]
    #[test_case(-45.0, true, -45.0; "minus 45 stays")]
    #[test_case(270.0, false, 270.0; "unlocked keeps 270")]
    #[test_case(-90.0, false, 270.0; "unlocked normalises minus 90")]
    fn an_upright_footprint_text_folds_its_angle_into_the_readable_half(
        rotation: f64,
        upright: bool,
        expected: f64,
    ) {
        let angle = draw_angle(rotation, upright);
        assert!(close(angle, expected), "{angle}");
    }

    fn placement(justify: Justify, angle: f64) -> Placement {
        Placement {
            size: Size {
                width: 1.0,
                height: 1.0,
            },
            pen: 0.15,
            italic: false,
            justify,
            position: Point { x: 10.0, y: 20.0 },
            angle,
        }
    }

    #[test]
    fn centred_text_has_its_glyph_centred_on_the_position() {
        // KiCad's centre justification: the line is moved back by half
        // its advance, and up by half the 1.17 block height from the
        // baseline-plus-height anchor, less the stroke fudge.
        let shape = shape("A", &placement(Justify::default(), 0.0));
        let apex = pt(&shape.strokes, 1, 1);
        assert!(close(apex.x, 10.0), "{apex:?}");
        let baseline = 20.0 + 1.0 - 0.15 * 0.052 - 1.17 / 2.0;
        assert!(close(apex.y, baseline - 20.0 / 21.0), "{apex:?}");
        assert!(close(pt(&shape.strokes, 1, 0).y, baseline + 1.0 / 21.0));
    }

    #[test]
    fn left_bottom_text_starts_a_fudge_right_of_its_position_and_sits_on_it() {
        let shape = shape(
            "I",
            &placement(
                Justify {
                    horizontal: Horizontal::Left,
                    vertical: Vertical::Bottom,
                    mirror: false,
                },
                0.0,
            ),
        );
        // I is "MWR[RF": its stroke sits 5/21 in from the left bearing.
        let stem = [pt(&shape.strokes, 0, 0), pt(&shape.strokes, 0, 1)];
        assert!(
            close(stem[0].x, 10.0 + 0.15 / 1.52 + 5.0 / 21.0),
            "{stem:?}"
        );
        let baseline = 20.0 + 1.0 - 0.15 * 0.052 - 1.17;
        assert!(close(stem[0].y, baseline + 1.0 / 21.0), "{stem:?}");
        assert!(close(stem[1].y, baseline - 20.0 / 21.0), "{stem:?}");
    }

    #[test]
    fn right_justified_text_ends_a_fudge_left_of_its_position() {
        let shape = shape(
            "II",
            &placement(
                Justify {
                    horizontal: Horizontal::Right,
                    vertical: Vertical::Center,
                    mirror: false,
                },
                0.0,
            ),
        );
        // The second I's right bearing is at the position less the fudge;
        // its stem is 5/21 before that.
        let second = [pt(&shape.strokes, 1, 0), pt(&shape.strokes, 1, 1)];
        assert!(
            close(second[0].x, 10.0 - 0.15 / 1.52 - 5.0 / 21.0),
            "{second:?}"
        );
    }

    #[test]
    fn a_second_line_sits_one_interline_lower() {
        let shape = shape("I\nI", &placement(Justify::default(), 0.0));
        let dy = pt(&shape.strokes, 1, 0).y - pt(&shape.strokes, 0, 0).y;
        assert!(close(dy, 1.68 * 0.9583), "{dy}");
        // The block is centred: two lines of 1.17 + interline.
        let baseline = 20.0 + 1.0 - 0.15 * 0.052 - f64::midpoint(1.17, 1.68 * 0.9583);
        assert!(close(pt(&shape.strokes, 0, 0).y, baseline + 1.0 / 21.0));
    }

    #[test]
    fn a_space_advances_sixteen_twenty_firsts_of_the_width() {
        let shape = shape("I I", &placement(Justify::default(), 0.0));
        let dx = pt(&shape.strokes, 1, 0).x - pt(&shape.strokes, 0, 0).x;
        assert!(close(dx, 10.0 / 21.0 + 16.0 / 21.0), "{dx}");
    }

    #[test]
    fn a_text_turned_90_degrees_reads_upwards() {
        // Positive angles turn counter-clockwise on the screen: the stem
        // of I, vertical at 0 degrees, lies along x, and what was up
        // (smaller y) is now left (smaller x).
        let flat = shape("I", &placement(Justify::default(), 0.0));
        let turned = shape("I", &placement(Justify::default(), 90.0));
        let stem = [pt(&turned.strokes, 0, 0), pt(&turned.strokes, 0, 1)];
        assert!(close(stem[0].y, stem[1].y), "{stem:?}");
        let flat_stem = [pt(&flat.strokes, 0, 0), pt(&flat.strokes, 0, 1)];
        assert!(
            close(stem[0].x - 10.0, flat_stem[0].y - 20.0)
                && close(stem[0].y - 20.0, -(flat_stem[0].x - 10.0)),
            "{stem:?} from {flat_stem:?}"
        );
    }

    #[test]
    fn mirrored_text_is_reflected_about_its_position() {
        let plain = shape(
            "I",
            &placement(
                Justify {
                    horizontal: Horizontal::Left,
                    vertical: Vertical::Center,
                    mirror: false,
                },
                0.0,
            ),
        );
        let mirrored = shape(
            "I",
            &placement(
                Justify {
                    horizontal: Horizontal::Left,
                    vertical: Vertical::Center,
                    mirror: true,
                },
                0.0,
            ),
        );
        let (a, b) = (pt(&plain.strokes, 0, 0), pt(&mirrored.strokes, 0, 0));
        assert!(
            close(a.x - 10.0, 10.0 - b.x) && close(a.y, b.y),
            "{a:?} {b:?}"
        );
    }

    #[test]
    fn the_knockout_box_is_the_strokes_grown_by_half_the_pen_and_the_margin() {
        let boxed = shape("I", &placement(Justify::default(), 0.0));
        let stem = [pt(&boxed.strokes, 0, 0), pt(&boxed.strokes, 0, 1)];
        let corners = boxed.knockout_box.expect("a box");
        // Pen 0.15: half is 0.075; the margin is a ninth of the height,
        // 0.111, which beats half the pen.
        let grow = 0.075 + 1.0 / 9.0;
        assert_point(corners[0], stem[0].x - grow, stem[1].y - grow);
        assert_point(corners[2], stem[0].x + grow, stem[0].y + grow);
        assert_eq!(
            shape("", &placement(Justify::default(), 0.0)).knockout_box,
            None
        );
    }

    #[test]
    fn the_block_size_is_the_widest_line_by_the_lines_height() {
        let size = Size {
            width: 1.0,
            height: 1.0,
        };
        let one = block_size("II", size);
        // Two I's: 10/21 each.
        assert!(close(one.width, 20.0 / 21.0), "{one:?}");
        assert!(close(one.height, 1.0), "{one:?}");
        let two = block_size("I\nIII", size);
        assert!(close(two.width, 30.0 / 21.0), "{two:?}");
        assert!(close(two.height, 1.0 + 1.68 * 0.9583), "{two:?}");
        assert!(close(block_size("", size).width, 0.0));
    }

    #[test]
    fn italic_glyphs_lean_right_at_the_top() {
        let mut placement = placement(Justify::default(), 0.0);
        placement.italic = true;
        let shape = shape("I", &placement);
        let stem = [pt(&shape.strokes, 0, 0), pt(&shape.strokes, 0, 1)];
        // The top (more negative y) shifts right by y/8.
        assert!(close(stem[1].x - stem[0].x, 21.0 / 21.0 / 8.0), "{stem:?}");
    }
}
